import java.util.List;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executor;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.AbstractQueuedSynchronizer;

public class Main {
    public static void main(String[] args) throws Exception {
        demonstrateAqsSkeleton();
        demonstrateRejectStrategy();
        demonstrateSingletonAndEvent();
    }

    static void demonstrateAqsSkeleton() throws InterruptedException {
        Mutex mutex = new Mutex();
        int[] counter = {0};
        CountDownLatch done = new CountDownLatch(2);
        Runnable task = () -> {
            for (int i = 0; i < 1000; i++) {
                mutex.lock();
                try {
                    counter[0]++;
                } finally {
                    mutex.unlock();
                }
            }
            done.countDown();
        };
        new Thread(task, "mutex-a").start();
        new Thread(task, "mutex-b").start();
        done.await();
        System.out.println("mutexCounter=" + counter[0]);
        assert counter[0] == 2000;
    }

    static void demonstrateRejectStrategy() throws InterruptedException {
        CountDownLatch release = new CountDownLatch(1);
        CountingRejectHandler handler = new CountingRejectHandler();
        ThreadPoolExecutor pool = new ThreadPoolExecutor(
                1, 1, 0, TimeUnit.SECONDS,
                new ArrayBlockingQueue<>(1),
                handler);
        pool.execute(() -> await(release));
        pool.execute(() -> { });
        pool.execute(() -> { throw new AssertionError("rejected task should not run"); });
        System.out.println("rejected=" + handler.rejected.get());
        assert handler.rejected.get() == 1;
        release.countDown();
        pool.shutdown();
        pool.awaitTermination(1, TimeUnit.SECONDS);
    }

    static void demonstrateSingletonAndEvent() throws InterruptedException {
        assert SafeSingleton.INSTANCE.value() == 42;
        EventBus bus = new EventBus(Runnable::run);
        AtomicInteger observed = new AtomicInteger();
        CountDownLatch delivered = new CountDownLatch(2);
        bus.register(event -> {
            observed.addAndGet(event.amount());
            delivered.countDown();
        });
        bus.register(event -> {
            observed.addAndGet(event.amount() * 10);
            delivered.countDown();
        });
        bus.publish(new OrderCreated("order-1", 3));
        delivered.await();
        System.out.println("eventObserved=" + observed.get());
        assert observed.get() == 33;
    }

    static final class Mutex {
        private final Sync sync = new Sync();

        void lock() { sync.acquire(1); }
        void unlock() { sync.release(1); }

        private static final class Sync extends AbstractQueuedSynchronizer {
            @Override
            protected boolean tryAcquire(int arg) {
                if (compareAndSetState(0, 1)) {
                    setExclusiveOwnerThread(Thread.currentThread());
                    return true;
                }
                return false;
            }

            @Override
            protected boolean tryRelease(int arg) {
                if (getState() == 0 || getExclusiveOwnerThread() != Thread.currentThread()) {
                    throw new IllegalMonitorStateException();
                }
                setExclusiveOwnerThread(null);
                setState(0);
                return true;
            }
        }
    }

    static final class CountingRejectHandler implements java.util.concurrent.RejectedExecutionHandler {
        final AtomicInteger rejected = new AtomicInteger();

        @Override
        public void rejectedExecution(Runnable task, ThreadPoolExecutor executor) {
            rejected.incrementAndGet();
        }
    }

    enum SafeSingleton {
        INSTANCE;
        int value() { return 42; }
    }

    record OrderCreated(String orderId, int amount) { }

    interface Listener {
        void onEvent(OrderCreated event);
    }

    static final class EventBus {
        private final List<Listener> listeners = new CopyOnWriteArrayList<>();
        private final Executor executor;

        EventBus(Executor executor) {
            this.executor = executor;
        }

        void register(Listener listener) {
            listeners.add(listener);
        }

        void publish(OrderCreated event) {
            for (Listener listener : listeners) {
                executor.execute(() -> listener.onEvent(event));
            }
        }
    }

    static void await(CountDownLatch latch) {
        try {
            latch.await();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
